thin=Side(style='thin',color='D9E1E8')

def add_sheet(name, rows, freeze='A2', widths=None, table=True):
    ws=wb.create_sheet(name)
    for row in rows: ws.append(row)
    for c in ws[1]:
        c.fill=PatternFill('solid',fgColor=navy); c.font=Font(color=white,bold=True); c.alignment=Alignment(wrap_text=True,vertical='center')
    ws.row_dimensions[1].height=34; ws.freeze_panes=freeze; ws.auto_filter.ref=ws.dimensions
    for row in ws.iter_rows():
        for c in row:
            c.alignment=Alignment(wrap_text=True,vertical='top'); c.border=Border(bottom=thin)
    if widths:
        for i,w in enumerate(widths,1): ws.column_dimensions[get_column_letter(i)].width=w
    else:
        for col in range(1,ws.max_column+1): ws.column_dimensions[get_column_letter(col)].width=22
    if table and ws.max_row>1:
        ref=f'A1:{get_column_letter(ws.max_column)}{ws.max_row}'
        t=Table(displayName='T'+''.join(ch for ch in name if ch.isalnum())[:20],ref=ref)
        t.tableStyleInfo=TableStyleInfo(name='TableStyleMedium2',showRowStripes=True,showFirstColumn=False,showLastColumn=False)
        ws.add_table(t)
    return ws

